def transform(grid):
    out=[row[:] for row in grid]
    # Fill the interior of each pair of diagonals that bound a wedge.
    # Identify outermost marks on each row; interior cells between them.
    for r,row in enumerate(grid):
        marks=[c for c,v in enumerate(row) if v]
        if len(marks)>=2:
            for c in range(min(marks)+1,max(marks)):
                if out[r][c]==0: out[r][c]=2
    return out
